    status: row.status,
    approvedCreditLimit: toPaisa2(row.approved_credit_limit),
    outstanding: toPaisa2(row.outstanding_amount),
    depositHeld: toPaisa2(row.deposit_held_amount),
    totalPaid: toPaisa2(row.total_paid_amount),
    activeBookingsCount: row.active_bookings_count ?? 0,
    totalBookingsCount: row.total_bookings_count ?? 0,
