function couponRowToResult(row, todayIso4) {
  const code = row.code;
  if (!row.is_active) return { ok: false, reason: `Promo code "${code}" is no longer active.` };
  if (row.valid_from > todayIso4) return { ok: false, reason: `Promo code "${code}" is not valid until ${row.valid_from}.` };
  if (row.valid_until < todayIso4) return { ok: false, reason: `Promo code "${code}" expired on ${row.valid_until}.` };
  if (row.max_redemptions != null && row.current_redemptions >= row.max_redemptions) {
    return { ok: false, reason: `Promo code "${code}" has reached its redemption limit.` };
  }
  const minRupees = Number(row.min_booking_amount ?? 0);
  const promo = {
    code,
    couponId: row.id,
    discountPercent: Number(row.discount_percent),
    active: true,
    validFrom: row.valid_from,
    validTo: row.valid_until,
    ...row.description ? { description: row.description } : {},
    ...minRupees > 0 ? { minSpendPaisa: rupees(minRupees) } : {}
  };
  return { ok: true, promo };
}
async function lookupCouponByCode(rawCode, todayIso4) {
  const code = rawCode.trim().toUpperCase();
  if (!code) return { ok: false, reason: "Enter a promo code." };
  const { data: data2, error } = await supabase.from("coupons").select(
    "id, code, description, discount_percent, min_booking_amount, valid_from, valid_until, max_redemptions, current_redemptions, is_active"
  ).eq("code", code).maybeSingle();
  if (error) return { ok: false, reason: "Could not check the promo code. Try again." };
  if (!data2) return { ok: false, reason: `Promo code "${code}" is invalid or expired.` };
  return couponRowToResult(data2, todayIso4);
}
