function expensesCsv(rows) {
  const header = [
    "Expense ID",
    "Bill No",
    "Date (AD)",
    "Date (BS)",
    "Category",
    "Sub-category",
    "Vendor",
    "Description",
    "Amount",
    "Reclaimable VAT",
    "Payment Method",
    "Status",
    "Paid By",
    "Submitted By",
    "Branch",
    "Recurring",
    "Linked to"
  ];
  return [
    header,
    ...rows.map((r) => {
      const bs = toBs(r.date);
      return [
        r.id,
        r.billNo ?? "",
        formatAd(r.date),
        bs ? formatBs(bs) : "",
        r.category,
        r.subCategory,
        r.vendor,
        r.description,
        formatMoney(r.amount),
        // §4.3 — null is "no tax invoice", which is not the same as zero credit.
        r.vat === null ? "" : formatMoney(r.vat),
        r.method,
        r.status,
        r.paidBy ?? "",
        r.submittedBy,
        r.branch,
        r.recurring ? "Yes" : "No",
        r.link ? `${r.link.kind} ${r.link.id}` : ""
      ];
    })
  ];
}
