// src/lib/queries/timesheet.ts
function getTimesheetRows(week) {
  const scale = week === "Last Week" ? 0.9 : 1;
  return TIMESHEET_DATA.map((entry2) => {
    const hrs = entry2.hrs.map((h) => Math.round(h * scale));
    const totalHrs = hrs.reduce((a, b) => a + b, 0);
    const pay = Math.round(totalHrs * (entry2.rate / 8));
    return {
      name: entry2.name,
      role: entry2.role,
      rate: entry2.rate,
      hrs,
      totalHrs,
      pay
    };
  });
}
function getTimesheetStats(rows) {
  let totalHours = 0;
  let totalPayroll = 0;
  let staffLogged = 0;
  let overtimeFlags = 0;
  for (const row of rows) {
    totalHours += row.totalHrs;
    totalPayroll += row.pay;
    if (row.totalHrs > 0) staffLogged++;
    if (row.hrs.some((h) => h > 8)) overtimeFlags++;
  }
  return {
    totalHours,
    totalPayroll,
    staffLogged,
    totalStaff: rows.length,
    overtimeFlags
  };
}
function exportTimesheetCsv(rows, week) {
  const header = ["Name", "Role", "Rate/hr (Rs)", ...TIMESHEET_DAYS, "Total Hours", "Total Pay (Rs)"];
  const csvRows = rows.map((r) => [
    r.name,
    r.role,
    String(r.rate),
    ...r.hrs.map(String),
    String(r.totalHrs),
    String(r.pay)
  ]);
  const csv = [header, ...csvRows].map((row) => row.map((cell3) => `"${cell3}"`).join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const filename = `payroll-${week === "Last Week" ? "lastweek" : "thisweek"}.csv`;
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}
