function getProductions() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY6);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch {
  }
  return [...SEED_PRODUCTIONS];
}
function saveProductions(items) {
  localStorage.setItem(STORAGE_KEY6, JSON.stringify(items));
}
function createProduction(item) {
  const all = getProductions();
  const nextNum = 100 + all.length + 1;
  const newProd = {
    ...item,
    id: `PRD-${nextNum}`
  };
  all.unshift(newProd);
  saveProductions(all);
  return newProd;
}
function updateProductionPhase(id2, phase) {
  const all = getProductions();
  const idx = all.findIndex((p) => p.id === id2);
  if (idx !== -1) {
    const existing = all[idx];
    if (existing) {
      all[idx] = { ...existing, phase };
      saveProductions(all);
    }
  }
  return all;
}
function getProductionStats(items) {
  let inShootCount = 0;
  let preProdCount = 0;
  let returnWrapCount = 0;
  let totalBudget = 0;
  let totalGearOut = 0;
  for (const p of items) {
    totalBudget += p.budgetNpr;
    if (p.phase === "Shoot") {
      inShootCount++;
      totalGearOut += p.gearCount;
    } else if (p.phase === "Pre-Production") {
      preProdCount++;
    } else {
      returnWrapCount++;
    }
  }
  return {
    totalCount: items.length,
    inShootCount,
    preProdCount,
    returnWrapCount,
    totalBudget,
    totalGearOut
  };
}
